/**
 * Shared types for the ledger service.
 *
 * Money is always represented in minor units (cents for USD, pence for GBP and
 * so on) so that no floating point arithmetic ever touches a ledger amount.
 */

/** ISO 4217 alphabetic currency code, upper case. */
export type CurrencyCode = string;

/** A refund request as it arrives from a merchant integration. */
export interface RefundRequest {
  /** Merchant that owns the refund. */
  merchantId: string;
  /** Caller supplied identifier for this submission. */
  requestId: string;
  /** Refund amount in minor units. Always positive. */
  amountMinor: number;
  /** ISO 4217 currency code of the refund amount. */
  currency: CurrencyCode;
  /** Optional free text captured for merchant support tooling. */
  reason: string | null;
}

export type RefundStatus = 'posted';

/** A refund that has been accepted and recorded by the service. */
export interface Refund {
  id: string;
  merchantId: string;
  requestId: string;
  amountMinor: number;
  currency: CurrencyCode;
  reason: string | null;
  status: RefundStatus;
  createdAt: string;
}

/**
 * Ledger entries are single sided. A refund moves money away from the
 * merchant, so it is recorded as a debit against the merchant balance.
